export function fbm(x, y, salt, seed = getWorldSeed()) {
  let value = 0;
  let amplitude = 0.5;
  let scale = 180;
  for (let octave = 0; octave < 5; octave++) {
    value += smoothNoise(x, y, scale, salt + octave * 31, seed) * amplitude;
    scale *= 0.48;
    amplitude *= 0.5;
  }
  return value;
}

