export function fbm(x, y, salt, seed = getWorldSeed(), baseScale = 180, octaves = 5) {
  let value = 0;
  let amplitude = 0.5;
  let scale = baseScale;
  let norm = 0;
  for (let octave = 0; octave < octaves; octave++) {
    value += smoothNoise(x, y, scale, salt + octave * 31, seed) * amplitude;
    norm += amplitude;
    scale *= 0.5;
    amplitude *= 0.5;
  }
  return norm > 0 ? value / norm : value;
}

